<script lang="ts">
  import Panel from './Panel.svelte';
  import Meter from './Meter.svelte';
  import Transactions from './Transactions.svelte';
  import Icon from '$lib/components/Icon.svelte';
  import { apiPost } from '$lib/api/client';
  import { number as n, text, type Model, type Actions } from './model';
  let { m, a }: { m: Model; a: Actions } = $props();
  let search = $state(''); let category = $state(''); let account = $state(''); let txType = $state(''); let page = $state(1);
  const filtered = $derived(m.transactions.filter(row => (!search || text(row.name).toLowerCase().includes(search.toLowerCase())) && (!category || text(row.categoryId) === category) && (!account || text(row.accountId) === account) && (!txType || row.type === txType)));
  const balances = (row: Record<string, unknown>) => n(row.calculatedBalance ?? row.balance ?? row.initialBalance);
  const credit = $derived(m.accounts.filter(row => row.type === 'Crédito'));
  const creditLimit = $derived(credit.reduce((sum, row) => sum + n(row.creditLimit), 0));
  const creditUsed = $derived(credit.reduce((sum, row) => sum + Math.max(0, -balances(row)), 0));
  let from = $state(''); let to = $state(''); let transferAmount = $state<number | undefined>(); let destinationAmount = $state<number | undefined>(); let transferName = $state(''); let transferError = $state(''); let saving = $state(false);
  const crossCurrency = $derived(from && to && m.accounts.find(c => c.id === n(from))?.currency !== m.accounts.find(c => c.id === n(to))?.currency);
  async function transfer(event: SubmitEvent) {
    event.preventDefault(); saving = true; transferError = '';
    try { await apiPost('/transfers', { name: transferName || m.t('cyberpunk.account_transfer'), amount: transferAmount, sourceAccountId: n(from), destinationAccountId: n(to), date: new Date().toISOString(), ...(crossCurrency ? { destinationAmount } : {}) }); transferAmount = undefined; transferName = ''; await a.refresh(); a.notify(m.t('cyberpunk.transfer_saved')); }
    catch (e) { transferError = e instanceof Error ? e.message : String(e); } finally { saving = false; }
  }
</script>

{#if m.route === 'cuentas'}
  <Panel title={m.t('cyberpunk.my_accounts')}>
    {#snippet action()}<button class="cp-button small" onclick={() => a.edit('accounts')}>+ {m.t('cyberpunk.add_account')}</button>{/snippet}
    <div class="cp-account-grid">{#each m.accounts.filter(row => row.type !== 'Crédito') as row}<article class="cp-account cp-tile"><span class="cp-account-brand"><Icon name={row.type === 'Efectivo' ? 'wallet' : 'building'} size={20}/><b>{text(row.bank) || text(row.name)}</b></span><span>{text(row.name)}</span><strong class="cp-number cp-yellow">{m.money(balances(row), text(row.currency) || m.currency)}</strong><small>{text(row.currency)}</small><div class="cp-card-footer"><button class="cp-link" onclick={()=>a.edit('account-detail',row)}>{m.t('cyberpunk.details')}</button><button class="cp-link" onclick={()=>a.edit('accounts',row)}>{m.t('receipts.edit')}</button><button class="cp-link cp-red" onclick={()=>a.edit('account-deactivate',row)}>{m.t('common.deactivate')}</button></div></article>{:else}<p class="cp-empty">{m.t('cyberpunk.add_an_account_to_get_started')}</p>{/each}</div>
  </Panel>
  <Panel title={m.t('cyberpunk.credit_cards')}><div class="cp-account-grid">{#each credit as row}<article class="cp-tile cp-credit"><div class="cp-card-heading"><Icon name="credit-card" size={22}/><strong>{text(row.name)}</strong><button class="cp-icon-button" aria-label={m.t('cyberpunk.edit_credit_card')} onclick={() => a.edit('accounts', row)}>···</button></div><div class="cp-key-values"><span>{m.t('accounts.credit_limit_label')}</span><b>{m.money(row.creditLimit)}</b><span>{m.t('cyberpunk.used')}</span><b class="cp-red">{m.money(Math.max(0, -balances(row)))}</b></div><Meter value={Math.max(0, -balances(row))} max={n(row.creditLimit)} tone={-balances(row) / n(row.creditLimit) > .7 ? 'red' : 'cyan'} label={m.t('reports.credit_title')}/><div class="cp-card-footer">{m.t('dashboard.available')}<strong>{m.money(n(row.creditLimit) - Math.max(0, -balances(row)))}</strong></div><button class="cp-button ghost small" onclick={()=>a.edit('account-detail',row)}>{m.t('cyberpunk.statement_history')}</button></article>{:else}<p class="cp-empty">{m.t('cyberpunk.no_credit_cards_yet')}</p>{/each}</div></Panel>
  <Panel title={m.t('cyberpunk.credit_utilization_summary')}><div class="cp-stats plain"><div class="cp-stat"><span>{m.t('cyberpunk.total_credit')}</span><strong>{m.money(creditLimit)}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.credit_used')}</span><strong class="cp-red">{m.money(creditUsed)}</strong><Meter value={creditUsed} max={creditLimit} tone="red" label={m.t('cyberpunk.used_credit')}/></div><div class="cp-stat"><span>{m.t('accounts.available_credit')}</span><strong>{m.money(creditLimit - creditUsed)}</strong></div></div></Panel>
{:else if m.route === 'transacciones'}
  <div class="cp-toolbar"><input aria-label={m.t('cyberpunk.filter_visible_transactions')} placeholder={m.t('cyberpunk.filter_visible_transactions_placeholder')} bind:value={search} oninput={() => page = 1}/><select aria-label={m.t('search.filter_account')} bind:value={account} onchange={() => page = 1}><option value="">{m.t('cyberpunk.all_accounts')}</option>{#each m.accounts as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select><select aria-label={m.t('search.filter_category')} bind:value={category} onchange={() => page = 1}><option value="">{m.t('cyberpunk.all_categories')}</option>{#each m.categories as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select><button class="cp-button" onclick={() => a.edit('transactions')}>+ {m.t('receipts.upload_new')}</button></div>
  <div class="cp-tabs">{#each [['',m.t('search.entity_all')],['Ingreso',m.t('search.type_income')],['Gasto',m.t('dashboard.expenses')]] as [value,label]}<button class:active={txType === value} onclick={() => { txType=value; page=1; }}>{label}</button>{/each}</div>
  <Panel title={m.t('cyberpunk.transaction_log')}><Transactions {m} {a} items={filtered.slice((page - 1) * 20, page * 20)}/><footer class="cp-pagination"><span>{Math.min((page - 1) * 20 + 1, filtered.length)}–{Math.min(page * 20, filtered.length)} / {filtered.length}{m.transactionTotal > 100 ? ` (${m.transactionTotal} ${m.t('cyberpunk.total')})` : ''}</span><div><button class="cp-button ghost small" disabled={page <= 1} onclick={() => page--}>‹</button><span>{page}</span><button class="cp-button ghost small" disabled={page * 20 >= filtered.length} onclick={() => page++}>›</button></div>{#if m.transactionTotal > 100}{/if}</footer></Panel>
{:else}
  <div class="cp-split">
    <Panel title={m.t('cyberpunk.new_transfer')}><form class="cp-form" onsubmit={transfer}><label>{m.t('search.filter_start')}<select bind:value={from} required><option value="">{m.t('subscriptions.form_account_placeholder')}</option>{#each m.accounts as row}<option value={text(row.id)}>{text(row.name)} · {m.money(balances(row),text(row.currency) || m.currency)}</option>{/each}</select></label><label>{m.t('search.filter_end')}<select bind:value={to} required><option value="">{m.t('subscriptions.form_account_placeholder')}</option>{#each m.accounts.filter(row => row.id !== n(from)) as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select></label><label>{m.t('receipts.form_amount')}<input required type="number" min="0.01" step="0.01" bind:value={transferAmount}/></label>{#if crossCurrency}<label>{m.t('cyberpunk.destination_amount')}<input required type="number" min="0.01" step="0.01" bind:value={destinationAmount}/></label>{/if}<label>{m.t('cyberpunk.description_optional')}<input bind:value={transferName}/></label>{#if transferError}<p class="cp-error" role="alert">{transferError}</p>{/if}<button class="cp-button" disabled={saving}>{saving ? '…' : m.t('cyberpunk.save_transfer')} →</button></form></Panel>
    <Panel title={m.t('cyberpunk.quick_transfers')}><div class="cp-quick-transfers">{#each m.accounts.slice(0,4) as row}<div><Icon name="wallet" size={24}/><span><b>{text(row.name)}</b><small>{text(row.bank) || text(row.currency)}</small></span><button class="cp-button small" onclick={() => a.edit('transfers', { id:0, destinationAccountId:row.id, name:m.t('cyberpunk.transfer_to') + text(row.name) })}>{m.t('dashboard.transfer')}</button></div>{/each}</div></Panel>
  </div>
  <Panel title={m.t('cyberpunk.transfer_history')}><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.t('receipts.form_date')}</th><th>{m.t('dashboard.description')}</th><th>{m.t('search.filter_start')}</th><th>{m.t('search.filter_end')}</th><th class="cp-right">{m.t('receipts.form_amount')}</th><th></th></tr></thead><tbody>{#each m.transfers as row}<tr><td>{m.date(row.date)}</td><td>{text(row.name)}</td><td>{m.account(row.sourceAccountId)}</td><td>{m.account(row.destinationAccountId)}</td><td class="cp-number cp-right">{m.money(row.amount)}</td><td><button class="cp-icon-button" aria-label={m.t('transfers.edit_tooltip')} onclick={() => a.edit('transfers',row)}>···</button><button class="cp-link cp-red" onclick={()=>a.edit('transfer-delete',row)}>{m.t('receipts.delete')}</button></td></tr>{:else}<tr><td colspan="6" class="cp-empty">{m.t('cyberpunk.no_transfers_yet')}</td></tr>{/each}</tbody></table></div></Panel>
{/if}
